143			const messageSecret = document.querySelector<HTMLMetaElement>('meta[name="vscode-markdown-editor-message-secret"]')?.content;
144			if (!messageSecret) {
145				throw new Error('Missing Markdown editor message secret');
146			}
147			this.#messageSecret = messageSecret;
148			this.#editEpoch = initialState.editEpoch;
