159			window.addEventListener('message', (event) => {
160				const message = event.data;
161				if (!message || typeof message !== 'object' || message.messageSecret !== this.#messageSecret) {
162					return;
163				}
164				if (this.#syntaxHighlighter.handleMessage(message)) {
165					return;
166				}
167				if (this.#linkPresentationProvider?.handleMessage(message)) {
168					return;
169				}
170				switch (message.type) {
171					case 'update': {
172						// `replaceSourceText` (not `sourceText.set`) applies authoritative host
173						// text: it maps the selection through the change and clears stale
174						// pending-paragraph state, so the caret stays valid after an undo shrinks
175						// the document. The guard stops this echoing back as a user edit.
176						if (typeof message.editEpoch !== 'number' || !Number.isInteger(message.editEpoch) || message.editEpoch < 0) {
177							break;
178						}
179						this.#editEpoch = message.editEpoch;
180						this.isUpdatingFromExtension = true;
181						this.model.replaceSourceText(new StringValue(message.content));
182						this.isUpdatingFromExtension = false;
183						break;
184					}
185					case 'codeBlockEditorProviders': {
186						const providers = readCodeBlockEditorProviderDefinitions(message.codeBlockEditorProviders);
187						this.#codeBlockEditorProviders = providers;
188						this.#embeddedCodeEditorFactory?.updateProviders(this.#createIframeProviders(providers));
189						break;
190					}
191					case 'resolvedCodeBlockEditor': {
192						if (typeof message.requestId !== 'number') {
193							break;
194						}
195						const resolve = this.#codeBlockEditorRequests.get(message.requestId);
196						if (resolve) {
197							this.#codeBlockEditorRequests.delete(message.requestId);
198							resolve(readResolvedCodeBlockEditor(message.descriptor));
199						}
200						break;
201					}
202					case 'codeBlockEditorHostTransportMessage': {
203						if (typeof message.runtimeId === 'string') {
204							this.#codeBlockEditorHostTransports.get(message.runtimeId)?.acceptMessage(message.message);
205						}
206						break;
207					}
208					case 'gutterMarkers': {
209						const markers: GutterMarker[] = message.markers.map((marker: { start: number; endExclusive: number; type: GutterMarker['type'] }) => ({
210							range: OffsetRange.fromTo(marker.start, marker.endExclusive),
211							type: marker.type,
212						}));
213						this.model.gutterMarkers.set(markers, undefined);
214						break;
215					}
