230						break;
231					}
232					case 'revealLinkTarget': {
233						const contentLength = this.model.sourceText.get().value.length;
234						if (typeof message.start === 'number' && Number.isInteger(message.start) && message.start >= 0
235							&& typeof message.endExclusive === 'number' && Number.isInteger(message.endExclusive) && message.endExclusive >= message.start
236							&& message.endExclusive <= contentLength
237							&& typeof message.selectionStart === 'number' && Number.isInteger(message.selectionStart) && message.selectionStart >= 0
238							&& message.selectionStart <= contentLength) {
