216	class FormatOnSaveParticipant implements ITextFileSaveParticipant {
217	
218		constructor(
219			@IConfigurationService private readonly configurationService: IConfigurationService,
220			@ICodeEditorService private readonly codeEditorService: ICodeEditorService,
221			@IInstantiationService private readonly instantiationService: IInstantiationService,
222		) {
223			// Nothing
224		}
225	
226		async participate(model: ITextFileEditorModel, context: ITextFileSaveParticipantContext, progress: IProgress<IProgressStep>, token: CancellationToken): Promise<void> {
227			if (!model.textEditorModel) {
228				return;
229			}
230			if (context.reason === SaveReason.AUTO) {
231				return undefined;
232			}
233	
234			const textEditorModel = model.textEditorModel;
235			const overrides = { overrideIdentifier: textEditorModel.getLanguageId(), resource: textEditorModel.uri };
236	
237			const nestedProgress = new Progress<{ displayName?: string; extensionId?: ExtensionIdentifier }>(provider => {
238				progress.report({
239					message: localize(
240						{ key: 'formatting2', comment: ['[configure]({1}) is a link. Only translate `configure`. Do not change brackets and parentheses or {1}'] },
241						"Running '{0}' Formatter ([configure]({1})).",
242						provider.displayName || provider.extensionId && provider.extensionId.value || '???',
243						createCommandUri('workbench.action.openSettings', 'editor.formatOnSave').toString(),
244					)
245				});
246			});
247	
248			const enabled = this.configurationService.getValue<boolean>('editor.formatOnSave', overrides);
249			if (!enabled) {
250				return undefined;
251			}
252	
253			const editorOrModel = findEditor(textEditorModel, this.codeEditorService) || textEditorModel;
254			const mode = this.configurationService.getValue<'file' | 'modifications' | 'modificationsIfAvailable'>('editor.formatOnSaveMode', overrides);
255	
256			if (mode === 'file') {
257				await this.instantiationService.invokeFunction(formatDocumentWithSelectedProvider, editorOrModel, FormattingMode.Silent, nestedProgress, token);
258	
259			} else {
260				const ranges = await this.instantiationService.invokeFunction(getModifiedRanges, isCodeEditor(editorOrModel) ? editorOrModel.getModel() : editorOrModel);
261				if (ranges === null && mode === 'modificationsIfAvailable') {
262					// no SCM, fallback to formatting the whole file iff wanted
263					await this.instantiationService.invokeFunction(formatDocumentWithSelectedProvider, editorOrModel, FormattingMode.Silent, nestedProgress, token);
264	
265				} else if (ranges) {
266					// formatted modified ranges
267					await this.instantiationService.invokeFunction(formatDocumentRangesWithSelectedProvider, editorOrModel, ranges, FormattingMode.Silent, nestedProgress, token, false);
268				}
269			}
270		}

